import React from "react";

export default function About() {
  return (
    <div className="about-page">

      {/* HERO */}
      <div className="hero">
        <h1>
          I’m a developer who turns <span>ideas into systems</span>.
        </h1>
      </div>

      {/* MAIN */}
      <div className="main">

        {/* LEFT SIDE */}
        <div className="story">

          <div className="line-block">
            <div className="dot"></div>
            <div className="text">
              <h2>Thinking Style</h2>
              <p>
                I approach problems by simplifying them into structured components.
                I first understand the system before writing code.This helps me focus on clarity and logical design before implementation.
              </p>
            </div>
          </div>

          <div className="line-block">
            <div className="dot"></div>
            <div className="text">
              <h2>How I Work</h2>
              <p>
                Build → Test → Improve → Repeat. I believe strong systems are built
                through iteration and continuous refinement.Each cycle helps me improve both code quality and system understanding.
              </p>
            </div>
          </div>

          <div className="line-block">
            <div className="dot"></div>
            <div className="text">
              <h2>What I Focus On</h2>
              <p>
                Full-stack development, UI clarity, backend logic, and building
                real-world applications that solve meaningful problems.I ensure my solutions are structured, scalable, and easy to maintain.
              </p>
            </div>
          </div>

        </div>

        {/* RIGHT SIDE */}
        <div className="side">

          {/* ABOUT BOX */}
          <div className="card main-card">
            <h2>👤 About Me</h2>

            <p>
              I am an Information Technology student passionate about building
              practical and scalable software solutions.
            </p>

            <p>
              I enjoy understanding systems deeply and converting ideas into
              clean, structured applications.
            </p>
          </div>

          {/* EDUCATION */}
          <div className="card">
            <h3>🎓 Education</h3>

            <p>B.Tech – Information Technology</p>
            <p className="muted">Panimalar Engineering College</p>

            <div className="row">
              <span>2023 – 2027</span>
              <span className="cgpa">CGPA: 8.81</span>
            </div>
          </div>

        </div>

      </div>

      {/* STATS */}
      <div className="stats">

        <div className="stat-card">
          <h3>5+</h3>
          <p>Projects</p>
        </div>

        <div className="stat-card">
          <h3>1+</h3>
          <p>Internships</p>
        </div>

        <div className="stat-card">
          <h3>3+</h3>
          <p>Certifications</p>
        </div>

      </div>

      {/* STYLE */}
      <style>{`

        .about-page {
          min-height: 100vh;
          padding: 20px 10%;
          font-family: "Poppins", sans-serif;
          background: radial-gradient(circle at top, #0b1220, #050816);
          color: white;
        }

        .hero h1 {
          font-size: 44px;
          line-height: 1.3;
        }

        .hero span {
          color: #38BDF8;
        }

        .main {
          display: grid;
          grid-template-columns: 1.2fr 1fr;
          gap: 40px;
          margin-top: 50px;
        }

        /* LEFT SIDE */
        .story {
          display: flex;
          flex-direction: column;
        }

        .line-block {
          display: flex;
          gap: 14px;
          margin-bottom: 28px;
        }

        .dot {
          width: 5px;
          height: 9px;
          margin-top: 7px;
          border-radius: 50%;
          background: #38BDF8;
          box-shadow: 0 0 8px #38BDF8;
        }

        .text h2 {
          color: #38BDF8;
          margin-bottom: 6px;
          font-size: 19px;
        }

        .text p {
          color: #cbd5e1;
          line-height: 1.65;
          margin-bottom: 6px;
        }

        /* RIGHT SIDE */
        .side {
          display: flex;
          flex-direction: column;
          gap: 16px;
        }

        .card {
          padding: 18px;
          border-radius: 14px;
          background: rgba(255,255,255,0.04);
          border: 1px solid rgba(56,189,248,0.15);
        }

        .main-card {
          border: 1px solid rgba(56,189,248,0.3);
          box-shadow: 0 0 18px rgba(56,189,248,0.08);
        }

        h2, h3 {
          color: #38BDF8;
          margin-bottom: 10px;
        }

        p {
          color: #cbd5e1;
          line-height: 1.6;
        }

        .muted {
          color: #94a3b8;
        }

        .row {
          display: flex;
          justify-content: space-between;
          margin-top: 10px;
        }

        .cgpa {
          color: #38BDF8;
          font-weight: 600;
        }

        /* STATS */
        .stats {
          margin-top: 50px;
          display: flex;
          gap: 20px;
        }

        .stat-card {
          flex: 1;
          text-align: center;
          padding: 20px;
          border-radius: 14px;
          background: rgba(255,255,255,0.04);
          border: 1px solid rgba(56,189,248,0.15);
        }

        .stat-card h3 {
          color: #38BDF8;
          font-size: 28px;
        }

        .stat-card p {
          color: #94a3b8;
        }

        @media (max-width: 900px) {
          .main {
            grid-template-columns: 1fr;
          }

          .stats {
            flex-direction: column;
          }

          .hero h1 {
            font-size: 32px;
          }
        }

      `}</style>

    </div>
  );
}
